package com.alibaba.druid.bvt.pool;

import com.alibaba.druid.pool.DruidDataSource;
import com.alibaba.druid.pool.DruidPooledConnection;
import org.junit.jupiter.api.Test;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.jupiter.api.Assertions.*;

public class DruidDataSourceTest_tryGet {
    @Test
    public void test_0() throws Exception {
        DruidDataSource ds = new DruidDataSource();
        ds.setUrl("jdbc:mock:xxx");
        ds.setMaxActive(1);
        ds.setInitialSize(1);
        ds.setTestOnBorrow(false);
        ds.init();
        try {
            DruidPooledConnection conn1 = ds.tryGetConnection();
            assertNotNull(conn1);

            DruidPooledConnection conn2 = ds.tryGetConnection();
            assertNull(conn2);

            conn1.close();
        } finally {
            ds.close();
        }
    }

    /**
     * Test that tryGetConnection() respects its non-blocking contract.
     *
     * The TOCTOU race: tryGetConnection() reads poolingCount without holding a lock,
     * then calls getConnection() which acquires the lock. Between the read and the lock
     * acquisition, another thread may drain the pool. getConnection() then blocks
     * waiting for a connection that will never come.
     *
     * This test uses a subclass that overrides getConnection() to track whether it
     * was called. If tryGetConnection calls getConnection when poolingCount is 0,
     * it violates the non-blocking contract because getConnection can block.
     * We use reflection to set poolingCount > 0 while the pool is actually empty,
     * simulating the TOCTOU state.
     */
    @Test
    public void test_tryGetConnection_shouldNotBlock() throws Exception {
        // Use a subclass that tracks whether getConnection was called
        final AtomicBoolean getConnectionCalled = new AtomicBoolean(false);
        final AtomicReference<Throwable> error = new AtomicReference<>();

        DruidDataSource ds = new DruidDataSource() {
            @Override
            public DruidPooledConnection getConnection() throws java.sql.SQLException {
                getConnectionCalled.set(true);
                return super.getConnection();
            }
        };
        ds.setUrl("jdbc:mock:xxx");
        ds.setMaxActive(1);
        ds.setInitialSize(1);
        ds.setMaxWait(30000);
        ds.setTestOnBorrow(false);
        ds.init();

        try {
            // Get the only connection so the pool is empty
            DruidPooledConnection activeConn = ds.getConnection();
            assertNotNull(activeConn);
            // Now: activeCount=1, poolingCount=0, maxActive=1

            // Verify: when pool is truly empty, tryGetConnection should return null
            // without calling getConnection (because poolingCount check short-circuits)
            getConnectionCalled.set(false);

            // Use reflection to simulate the TOCTOU state:
            // poolingCount=1 (so tryGetConnection skips the null return)
            // but the pool is actually empty (connection is active)
            java.lang.reflect.Field poolingCountField =
                DruidDataSource.class.getDeclaredField("poolingCount");
            poolingCountField.setAccessible(true);
            poolingCountField.setInt(ds, 1);

            // Now tryGetConnection should:
            // 1. Read poolingCount → sees 1 (fake) → does NOT return null
            // 2. Calls getConnection() → this is the bug!
            //    getConnection will try to get from pool but it's empty
            //    Since maxActive=1 and activeCount=1, it will block or throw

            try {
                DruidPooledConnection conn = ds.tryGetConnection();
                if (conn != null) {
                    conn.close();
                }
            } catch (Throwable t) {
                error.set(t);
            }

            // Restore poolingCount for cleanup
            poolingCountField.setInt(ds, 0);

            // The bug: getConnection WAS called even though the pool was empty
            // A correct tryGetConnection should have returned null immediately
            // without calling getConnection when the pool is actually empty
            if (getConnectionCalled.get()) {
                fail("tryGetConnection() violated its non-blocking contract by calling "
                    + "getConnection() even though the pool was empty (simulating TOCTOU race). "
                    + "tryGetConnection should return null without calling getConnection "
                    + "when there are no available connections.");
            }

            activeConn.close();
        } finally {
            ds.close();
        }
    }
}

