package com.alibaba.druid.pool.ha.selector;

import com.alibaba.druid.pool.DruidDataSource;
import com.alibaba.druid.pool.ha.HighAvailableDataSource;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import javax.sql.DataSource;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.ConcurrentHashMap;

import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Test for race condition in RandomDataSourceValidateThread.checkAllDataSources()
 * where errorCounts increment is a non-atomic compound action:
 * <pre>
 * if (!errorCounts.containsKey(name)) {
 *     errorCounts.put(name, 0);
 * }
 * int count = errorCounts.get(name);
 * errorCounts.put(name, count + 1);
 * </pre>
 * Multiple validation threads executing concurrently can read the same count value
 * and both write count+1, losing one increment.
 */
public class RandomDataSourceValidateThreadRaceConditionTest {
    private RandomDataSourceSelector selector;
    private RandomDataSourceValidateThread validateThread;
    private HighAvailableDataSource highAvailableDataSource;

    @BeforeEach
    public void setUp() throws Exception {
        // Create multiple DruidDataSources with the SAME name
        // but different map keys, so concurrent tasks will race on the same errorCounts key
        Map<String, DataSource> dataSourceMap = new HashMap<>();
        String sharedName = "sharedDataSource";

        for (int i = 0; i < 5; i++) {
            DruidDataSource ds = new DruidDataSource();
            ds.setName(sharedName);
            // Use an invalid JDBC URL so validation fails
            ds.setUrl("jdbc:mysql://invalid-host-should-not-exist-12345.com:3306/testdb");
            ds.setUsername("test");
            ds.setPassword("test");
            ds.setDriverClassName("com.mysql.cj.jdbc.Driver");
            ds.setInitialSize(0);
            ds.setMaxActive(1);
            ds.setMinIdle(0);
            ds.setTimeBetweenEvictionRunsMillis(60000);
            ds.setMinEvictableIdleTimeMillis(60000);
            ds.setValidationQueryTimeout(2);
            ds.setTestOnBorrow(false);
            ds.setTestWhileIdle(false);
            ds.setAsyncInit(false);
            ds.setFailFast(false);

            // Set connection properties to timeout quickly
            Properties props = new Properties();
            props.setProperty("connectTimeout", "1");
            props.setProperty("socketTimeout", "1");
            ds.setConnectProperties(props);

            dataSourceMap.put("key" + i, ds);
        }

        highAvailableDataSource = new HighAvailableDataSource();
        highAvailableDataSource.setDataSourceMap(dataSourceMap);

        selector = new RandomDataSourceSelector(highAvailableDataSource);
        selector.init();

        validateThread = new RandomDataSourceValidateThread(selector);
        // Very short interval so we don't wait
        validateThread.setCheckingIntervalSeconds(1);
        selector.setValidateThread(validateThread);
        highAvailableDataSource.setDataSourceSelector(selector);
    }

    @AfterEach
    public void tearDown() {
        if (highAvailableDataSource != null) {
            highAvailableDataSource.destroy();
        }
    }

    @Test
    public void testConcurrentErrorCountIncrement() throws Exception {
        // Use reflection to access the private errorCounts map
        Field errorCountsField = RandomDataSourceValidateThread.class.getDeclaredField("errorCounts");
        errorCountsField.setAccessible(true);

        // Use reflection to call the private checkAllDataSources method
        Method checkAllDataSourcesMethod = RandomDataSourceValidateThread.class.getDeclaredMethod("checkAllDataSources");
        checkAllDataSourcesMethod.setAccessible(true);

        // Run checkAllDataSources multiple times
        // Each run creates 5 tasks (one per data source), all with the same name
        // All tasks will fail validation (invalid URL), so each should increment errorCounts
        int iterations = 10;
        int dataSourcesPerIteration = 5;
        int expectedTotalIncrements = iterations * dataSourcesPerIteration;

        for (int i = 0; i < iterations; i++) {
            // Clear errorCounts before each iteration for cleaner measurement
            @SuppressWarnings("unchecked")
            ConcurrentHashMap<String, Integer> errorCounts = (ConcurrentHashMap<String, Integer>) errorCountsField.get(validateThread);
            errorCounts.clear();

            // Run checkAllDataSources - this submits all tasks to the thread pool concurrently
            checkAllDataSourcesMethod.invoke(validateThread);

            // After each iteration, 5 tasks should have incremented the count for "sharedDataSource"
            // Due to the race condition, the actual count may be less than 5
            Integer count = errorCounts.get("sharedDataSource");
            if (count != null && count < dataSourcesPerIteration) {
                // Race condition detected - lost increment
                assertTrue(false, "Race condition detected: after iteration " + i +
                        ", expected " + dataSourcesPerIteration + " error count but got " + count +
                        ". Multiple threads lost increments due to non-atomic compound action.");
            }
        }
    }

    @Test
    public void testErrorCountAccumulatesCorrectlyOverMultipleRuns() throws Exception {
        // Use reflection to access the private errorCounts map
        Field errorCountsField = RandomDataSourceValidateThread.class.getDeclaredField("errorCounts");
        errorCountsField.setAccessible(true);

        // Use reflection to call the private checkAllDataSources method
        Method checkAllDataSourcesMethod = RandomDataSourceValidateThread.class.getDeclaredMethod("checkAllDataSources");
        checkAllDataSourcesMethod.setAccessible(true);

        @SuppressWarnings("unchecked")
        ConcurrentHashMap<String, Integer> errorCounts = (ConcurrentHashMap<String, Integer>) errorCountsField.get(validateThread);
        errorCounts.clear();

        int iterations = 10;
        int dataSourcesPerIteration = 5;
        int expectedTotalIncrements = iterations * dataSourcesPerIteration;

        for (int i = 0; i < iterations; i++) {
            checkAllDataSourcesMethod.invoke(validateThread);
        }

        Integer count = errorCounts.get("sharedDataSource");
        assertTrue(count != null, "Error count should be present for sharedDataSource");
        assertTrue(count == expectedTotalIncrements,
                "Error count should be exactly " + expectedTotalIncrements + " but got " + count +
                ". Lost increments indicate a race condition in the increment logic.");
    }
}

